// ⛔⛔ D56 · THE EXTENSION SAYS "NOTHING IS PREPARED" — for a job whose résumé the user generated.
//
// Owner, 10-07: on an Amazon application page the toolbar said "Nothing is prepared for
// https://account.amazon.jobs. Open the application from your Draft queue." Two causes, and both are
// pinned here: (1) a packet was matched on ONE origin, and Amazon's posting (www.amazon.jobs) and its
// application (account.amazon.jobs) are two; (2) a résumé generated by hand produced no packet at all.
//
// What runs: the REAL extension handoff (extension/gated-handoff.js) against the REAL routes
// (routes/apply.js) on the full schema, with chrome.* stubbed at the one seam a browser owns —
// executeScript. The probe reads the form's controls from the page the LOCAL fake ATS actually
// serves (scripts/fakeAts.js, the D56 two-origin section: posting on localhost, application on
// 127.0.0.1); the fill records the plan it was handed. Nothing reaches an employer.
import test from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import net from "node:net";
import { spawn } from "node:child_process";
import express from "express";
import Database from "better-sqlite3";
import { MIGRATIONS } from "../scripts/migrations.js";
import { at } from "../test-support/sourceAnchors.js";
import applyRoutes, { capturedAtsAtApply } from "../routes/apply.js";
import {
  APPLY_ORIGIN_FAMILIES, packetOrigins, jobIdOf, pageMatchesPacket,
} from "../services/applyOrigins.js";
import { handoffMessage, copySheetRows } from "../services/manualHandoff.js";
import {
  runGatedHandoff, prepareAndFill, recordSubmitted, packetFillsOrigin, originsOf, savePacketForTab,
} from "../extension/gated-handoff.js";

const read = (p) => fs.readFileSync(p, "utf8").replace(/\r\n/g, "\n");

// ── The local fake ATS, on a free port ────────────────────────────────────────────────────────────
const freePort = () => new Promise((resolve) => {
  const s = net.createServer().listen(0, () => { const { port } = s.address(); s.close(() => resolve(port)); });
});
let ATS_PORT, atsProc, POSTING, APPLY, FAMILIES;
test.before(async () => {
  ATS_PORT = await freePort();
  atsProc = spawn(process.execPath, ["scripts/fakeAts.js"], { env: { ...process.env, PORT: String(ATS_PORT) }, stdio: "ignore" });
  POSTING = `http://localhost:${ATS_PORT}`;
  APPLY = `http://127.0.0.1:${ATS_PORT}`;
  // The family a deployment would carry for this ATS — registered through the routes' seam, as the
  // table in services/applyOrigins.js carries Amazon's.
  FAMILIES = [...APPLY_ORIGIN_FAMILIES,
    { ats: "fake-two-origin", origins: [POSTING, APPLY], jobIdPattern: /\/twoorigin\/(?:jobs|apply)\/(\d+)/ }];
  for (let i = 0; i < 100; i++) {
    try { const r = await fetch(`${POSTING}/twoorigin/jobs/1`); if (r.ok) return; } catch {}
    await new Promise(r => setTimeout(r, 50));
  }
  throw new Error("fake ATS did not start");
});
test.after(() => { atsProc?.kill(); });

